import {ToolRegistry} from './registry.js';

// specs/hal-engine-tool-input-validation/spec.md#1
it('rejects a missing required field before execution', async () => {
  const registry = new ToolRegistry();
  const execute = jest.fn(async () => 'ok');
  registry.register(
    {
      name: 'weather',
      description: 'forecast',
      inputSchema: {type: 'object', properties: {location: {type: 'string'}}, required: ['location']},
    },
    execute
  );
  const response = await registry.execute('weather', {});
  expect(response.result).toMatch(/location.*required|required.*location/i);
  expect(execute).not.toHaveBeenCalled();
});
import {jest} from '@jest/globals';
import {Ajv} from 'ajv';
import {ToolRegistry} from './registry.js';

describe('ToolRegistry schema compilation', () => {
  // specs/hal-engine-tool-input-validation/spec.md#5
  it('rejects an invalid static schema at registration with the tool name', () => {
    const registry = new ToolRegistry();
    expect(() =>
      registry.register(
        {name: 'broken', description: 'invalid schema', inputSchema: {type: 'invalid'}},
        async () => 'unused'
      )
    ).toThrow(/broken/);
  });
});

// specs/hal-engine-tool-input-validation/spec.md#7
it('caches dynamic schema validators by object reference', async () => {
  const registry = new ToolRegistry();
  const schema = {type: 'object', properties: {location: {type: 'string'}}};
  const otherSchema = {type: 'object', properties: {location: {type: 'number'}}};
  let currentSchema = schema;
  registry.register(
    () => ({name: 'dynamic', description: 'dynamic schema', inputSchema: currentSchema}),
    async () => 'ok'
  );
  const compile = jest.spyOn(Ajv.prototype, 'compile');
  try {
    await registry.execute('dynamic', {});
    await registry.execute('dynamic', {});
    currentSchema = otherSchema;
    await registry.execute('dynamic', {});
    currentSchema = schema;
    await registry.execute('dynamic', {});
    expect(compile).toHaveBeenCalledTimes(2);
  } finally {
    compile.mockRestore();
  }
});
