// specs/hal-engine-tool-input-validation/spec.md#1
it('reports the full path of a missing nested property', async () => {
  const registry = new ToolRegistry();
  registry.register(
    {name: 'weather', description: 'forecast', inputSchema: {type: 'object', properties: {address: {type: 'object', required: ['location']}}}},
    async () => 'ok'
  );
  expect(await registry.execute('weather', {address: {}})).toEqual({
    result: expect.stringMatching(/\\/address\\/location.*required/),
  });
});
EOF
